import{_ as o,o as s,c as d,a2 as t}from"./chunks/framework.CuUVYbLV.js";const f=JSON.parse('{"title":"会话工具实现","description":"rolebox 六个会话内省工具的内部实现 — ISessionClient 端口、类型模型、ID 语义、与持久化的关系","frontmatter":{"title":"会话工具实现","description":"rolebox 六个会话内省工具的内部实现 — ISessionClient 端口、类型模型、ID 语义、与持久化的关系"},"headers":[],"relativePath":"04-Advanced/session-tools.md","filePath":"04-Advanced/session-tools.md"}'),c={name:"04-Advanced/session-tools.md"};function a(i,e,n,r,l,p){return s(),d("div",null,[...e[0]||(e[0]=[t(`<h1 id="会话工具-session-tools" tabindex="-1">会话工具（Session Tools） <a class="header-anchor" href="#会话工具-session-tools" aria-label="Permalink to &quot;会话工具（Session Tools）&quot;">​</a></h1><p>六个会话工具让代理读取 harness 里的历史会话：列出、读取、搜索、取详情、看文件变更、分叉。 本页讲它们的实现——端口抽象、类型模型、ID 语义、与持久化的边界，以及每个工具在内部做了什么。</p><blockquote><p><strong>本页边界</strong>：六个工具的<strong>参数与返回格式</strong>见<a href="/rolebox-docs/03-Reference/tools/session-memory-tools.html">会话与记忆工具</a>；用它们做记忆合并的完整流程见<a href="/rolebox-docs/04-Advanced/memory-system.html">记忆系统</a>与<a href="/rolebox-docs/02-Guide/tutorial/07-memory.html">教程 07 让代理记住你</a>；调度任务的按时间桶查询属于 dispatch 域，见<a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a>。</p></blockquote><h2 id="子系统结构" tabindex="-1">子系统结构 <a class="header-anchor" href="#子系统结构" aria-label="Permalink to &quot;子系统结构&quot;">​</a></h2><p>会话工具是<strong>只读适配层</strong>：角色不拥有会话存储，只通过一个端口读取 harness 持有的会话日志。</p><p>端口是 <code>ISessionClient</code>（<code>src/platform/ports/session-client.ts</code>），它把平台差异收敛成一组方法：<code>list</code> / <code>get</code> / <code>messages</code> / <code>children</code> / <code>todo</code> / <code>diff</code> / <code>fork</code> / <code>status</code> / <code>prompt</code> / <code>promptSync</code> / <code>create</code> / <code>abort</code>，加上可选的 <code>compact</code>。端口自己不做任何 I/O，也不允许 import 具体平台的 SDK。</p><p>三个 harness 各自提供实现：<code>src/platform/adapters/opencode/session.ts</code>、<code>src/platform/adapters/pi/session.ts</code>、<code>src/platform/adapters/dsh/session.ts</code>。<code>src/session/client.ts</code> 保留了一个向后兼容别名，把旧的 <code>SessionClientWrapper</code> 指到 OpenCode 适配器上；新代码应当直接用端口类型。</p><p>注册发生在共享装配层：<code>src/platform/tool-assembly.ts</code> 的 <code>buildCanonicalTools()</code> 只有在调用方传入 <code>sessionClient</code> 时才注册这六个工具，否则整个会话工具面不存在。三个平台都会传入自己的适配器，因此在 v1.9.0 上会话工具对三者都可用。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>6 个工具 → src/session/session-browse-tools.ts   session_list / session_search</span></span>
<span class="line"><span>         → src/session/session-inspect-tools.ts  session_read / session_info / session_diff / session_fork</span></span>
<span class="line"><span>         → src/session/tools.ts                  统一再导出</span></span></code></pre></div><h2 id="类型模型" tabindex="-1">类型模型 <a class="header-anchor" href="#类型模型" aria-label="Permalink to &quot;类型模型&quot;">​</a></h2><p>工具之间传递的是 <code>src/session/types.ts</code> 里的结构，而不是各平台的原生对象：</p><table tabindex="0"><thead><tr><th>类型</th><th>关键字段</th><th>用途</th></tr></thead><tbody><tr><td><code>SessionInfo</code></td><td><code>id</code> / <code>projectID</code> / <code>directory</code> / <code>parentID?</code> / <code>title</code> / <code>version</code> / <code>time{created,updated,compacting?}</code> / <code>summary?</code></td><td>会话元数据；<code>summary.diffs</code> 存在时附带文件变更概览</td></tr><tr><td><code>Message</code></td><td><code>info: MessageInfo</code> + <code>parts: Part[]</code></td><td>一条消息与其所有片段</td></tr><tr><td><code>Part</code></td><td><code>text</code> / <code>reasoning</code> / <code>tool</code> / <code>step-finish</code> 四种，其余按通用片段保留</td><td>渲染与搜索的输入</td></tr><tr><td><code>ToolPart.state</code></td><td><code>pending</code> / <code>running</code> / <code>completed</code> / <code>error</code> 四态</td><td>工具调用在会话中的落点</td></tr><tr><td><code>FileDiff</code></td><td><code>file</code> / <code>before</code> / <code>after</code> / <code>additions</code> / <code>deletions</code></td><td><code>session_diff</code> 与统计的输入</td></tr><tr><td><code>SessionStats</code></td><td>token 分项、成本、工具频次、模型分布、增删行数</td><td><code>session_info</code> 的聚合结果</td></tr><tr><td><code>SearchMatch</code></td><td>会话、消息、角色、命中文本与前后文</td><td><code>session_search</code> 的结果单元</td></tr><tr><td><code>SessionStatus</code></td><td><code>idle</code> / <code>retry{attempt,message,next}</code> / <code>busy</code></td><td><code>session_info</code> 的 <code>Status</code> 行</td></tr><tr><td><code>Todo</code></td><td><code>content</code> / <code>status</code> / <code>priority</code> / <code>id</code></td><td>待办进度（不在会话日志里，单独查询）</td></tr></tbody></table><p><code>MessageInfo.role</code> 的类型是 <code>&quot;user&quot; | &quot;assistant&quot; | (string &amp; {})</code>：适配器特有的角色（例如 Pi 的 <code>toolResult</code>）被原样保留，避免工具输出被误判成助手正文。</p><h2 id="id-语义" tabindex="-1">ID 语义 <a class="header-anchor" href="#id-语义" aria-label="Permalink to &quot;ID 语义&quot;">​</a></h2><p>会话 ID 由 harness 生成，rolebox 全程透传，不铸造也不改写：</p><ul><li><code>session_list</code> 输出的 ID 就是后续 <code>session_read</code> / <code>session_info</code> / <code>session_diff</code> / <code>session_fork</code> 要回填的值；</li><li><code>parentID</code> 表达父子关系（分叉与子会话）；<code>session_fork</code> 成功后返回一个全新的 ID，新旧会话此后独立演进；</li><li><code>message_id</code> 是会话<strong>内部</strong>的消息标识，只被 <code>session_diff</code>（取该消息之前的差异）与 <code>session_fork</code>（在该消息处分叉）使用。</li></ul><p>历史上有一个坑：<code>shortId()</code>（<code>src/session/tool-helpers.ts</code>）会把超过 12 字符的 ID 截成 <code>xxxxxxxxxxxx...</code>，它曾被用在会话表格的 ID 列上，导致表格里的 ID 无法回填。v1.8.0 起会话列表与搜索结果表改为输出完整 ID。</p><p><code>shortId()</code> 目前只剩两处展示性用途：<code>session_read</code> 遇到没有消息的会话时提示里的 ID，以及 <code>session_fork</code> 成功块里「在哪个消息处分叉」那一行的消息引用。两者都不承担回填职责。</p><h2 id="六个工具的实现要点" tabindex="-1">六个工具的实现要点 <a class="header-anchor" href="#六个工具的实现要点" aria-label="Permalink to &quot;六个工具的实现要点&quot;">​</a></h2><h3 id="session-list" tabindex="-1">session_list <a class="header-anchor" href="#session-list" aria-label="Permalink to &quot;session_list&quot;">​</a></h3><p>先按 <code>project_path</code>（缺省取工具上下文的 <code>directory</code>）调用 <code>client.list()</code>，再用 <code>from_date</code> / <code>to_date</code> 按 <code>time.created</code> 过滤——日期解析失败（<code>NaN</code>）时该过滤器被静默忽略，不报错。之后按 <code>time.updated</code> 倒序、按 <code>limit</code> 截断，最后对每个入选会话再调一次 <code>client.messages()</code> 数消息条数，交给 <code>formatSessionListTable</code> 渲染。</p><p>这里有一个值得注意的成本特征：<strong>消息数是逐会话读取后统计的</strong>，所以列出 20 个会话会产生一次列表查询加 20 次消息查询。</p><p>表格的固定表头是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| Session ID | Title | Messages | Date Range | Duration |</span></span></code></pre></div><p>行内容随环境变化。列表为空时返回 <code>No sessions found.</code>。</p><h3 id="session-search" tabindex="-1">session_search <a class="header-anchor" href="#session-search" aria-label="Permalink to &quot;session_search&quot;">​</a></h3><p>搜索是<strong>纯子串匹配</strong>，不是模糊检索：默认大小写不敏感，逐条消息比对。参与匹配的文本默认只有非 <code>ignored</code> 的 text 片段；打开 <code>include_tool_output</code> 后，状态为 <code>completed</code> 的工具输出也进入匹配（<code>error</code> / <code>pending</code> 状态的输出不参与）。</p><p>命中的片段用 80 字符窗口取前后文（各截到窗口一半再加省略号）。搜索范围有硬上限：跨会话搜索最多扫描 200 个会话，命中数达到 <code>limit</code> 就提前停止。若因为上限而被截断，结果末尾会追加一行 <code>(searched first 200 sessions only)</code>；若在截断范围内一条都没命中，则直接返回「前 200 个会话中没有匹配」的提示，而不是空结果。</p><p>markdown 输出最多展示 20 条命中，多出的部分折叠成一行计数提示；<code>format: &quot;json&quot;</code> 则返回完整的匹配数组。</p><h3 id="session-read" tabindex="-1">session_read <a class="header-anchor" href="#session-read" aria-label="Permalink to &quot;session_read&quot;">​</a></h3><p><code>client.get()</code> 先确认会话存在，不存在返回 <code>Session not found: &lt;id&gt;</code>；没有消息时返回 <code>Session &quot;&lt;title&gt;&quot; (&lt;shortId&gt;) has no messages.</code>。之后拉取消息并按 <code>offset</code> 切片，拼接一段头部（标题、完整 ID、创建/更新时间、时长），再交给 <code>formatMessages</code>。</p><p>过滤发生在<strong>渲染阶段</strong>而不是取数阶段：<code>role_filter</code> 与 <code>tool_filter</code> 在遍历消息时跳过不匹配的项。每条 text 片段截断到 500 字符；reasoning 片段只在打开 <code>include_thinking</code> 时输出；工具输出只在打开 <code>include_tool_results</code> 时附在工具行之后。消息编号用 <code>offset + 序号</code> 还原成会话内的绝对序号，所以分页读取时编号是连续的。<code>include_todos</code> 打开时在末尾追加一节待办清单。</p><h3 id="session-info" tabindex="-1">session_info <a class="header-anchor" href="#session-info" aria-label="Permalink to &quot;session_info&quot;">​</a></h3><p>一次 <code>collectSessionAnalytics()</code>（<code>src/session/tool-helpers.ts</code>）走完所有数据：拉消息、子会话、待办、文件差异与会话状态，遍历消息累加助手消息的 token 与成本（input / output / reasoning / cache read / cache write）并按 <code>provider/model</code> 计数，同时统计所有消息里 <code>tool</code> 片段的调用频次，最后把文件差异的增删行数累加。</p><p>渲染顺序固定：会话元数据（存在父会话时输出 <code>Parent Session</code>，存在 <code>summary.diffs</code> 时输出 <code>Summary</code>）、<code>Messages</code> / <code>Children</code> / <code>Status</code> 三行、<code>### Token Usage</code>、总成本、<code>### Models Used</code>（按模型名排序）、<code>### Tool Usage</code>（按调用次数降序）、<code>### File Changes</code>（有差异时才输出）、<code>### Todo Progress</code>（有待办时才输出）。</p><h3 id="session-diff" tabindex="-1">session_diff <a class="header-anchor" href="#session-diff" aria-label="Permalink to &quot;session_diff&quot;">​</a></h3><p>只调一次 <code>client.diff(session_id, { messageID })</code>，把结果交给 <code>formatDiff</code>：先输出 <code>Files changed</code> / <code>Additions</code> / <code>Deletions</code> 三行汇总，再对每个文件输出 <code>--- a/&lt;path&gt;</code> 与 <code>+++ b/&lt;path&gt;</code>，随后是本文件的差异体。</p><p><strong>实现细节</strong>：差异体不是 LCS 或 Myers 对齐，而是<strong>按行号位置</strong>逐行比较 <code>before</code> 与 <code>after</code>——第 i 行不同就输出一行 <code>-</code> 与一行 <code>+</code>，相同则输出一行前导空格的上下文行。因此插入或删除整行时，后续所有行都会被报告为「删除 + 新增」。它给出的是可读的变更对照，不是可 <code>patch</code> 应用的标准 diff。</p><p>无变更时返回 <code>No file changes in this session.</code>。要比较两个会话，需要分别取差异后自行对照——这个工具的参数里没有第二个会话 ID。</p><h3 id="session-fork" tabindex="-1">session_fork <a class="header-anchor" href="#session-fork" aria-label="Permalink to &quot;session_fork&quot;">​</a></h3><p>先 <code>client.get()</code> 证明会话存在，再 <code>client.fork(session_id, { messageID })</code>。省略 <code>message_id</code> 时在最新消息处分叉。失败被明确分成两种文案：给了 <code>message_id</code> 时说明会话存在、分叉被拒可能源于无效的消息 ID；没给时只说分叉被拒，不提消息 ID，也不再声称会话「可能不存在」——这是 v1.8.0 修正的措辞。</p><p>成功时返回 <code>## Session Forked Successfully</code> 块，列出原会话与新会话的<strong>完整</strong> ID、新会话创建时间、分叉点，并提示新会话只是分叉点之前的副本。</p><h2 id="与持久化的关系" tabindex="-1">与持久化的关系 <a class="header-anchor" href="#与持久化的关系" aria-label="Permalink to &quot;与持久化的关系&quot;">​</a></h2><p>会话日志的所有权在 harness，不在 rolebox：</p><ul><li>六个工具读到的每一个字节都经过 <code>ISessionClient</code>，rolebox 侧没有会话数据库，也不写 harness 的会话日志；</li><li><code>session_fork</code> 是唯一会<strong>创建</strong>状态的操作，而创建的仍是 harness 的会话，rolebox 只是转发；</li><li>rolebox 自己的持久化只落在工作区目录：记忆库是 <code>.rolebox/memory.db</code>，函数运行时与信号台账等状态在 <code>.rolebox/state/</code> 下按工作区哈希命名。</li></ul><p>这条边界解释了一个常见困惑：会话工具的可见范围就是当前 harness 与当前工作区。换一个工作区目录、换一个 harness，看到的是另一批会话。</p><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><h3 id="定位并检查一个会话" tabindex="-1">定位并检查一个会话 <a class="header-anchor" href="#定位并检查一个会话" aria-label="Permalink to &quot;定位并检查一个会话&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>session_list(from_date=&quot;2026-07-01&quot;, to_date=&quot;2026-07-15&quot;, limit=50)</span></span>
<span class="line"><span>session_info(session_id=&quot;ses_abc123&quot;)</span></span>
<span class="line"><span>session_read(session_id=&quot;ses_abc123&quot;, include_tool_results=true, limit=50)</span></span></code></pre></div><p>先按日期收敛候选，用详情页判断这条会话值不值得细读（token、成本、工具分布、文件变更），再带工具输出读取正文。要读很长会话时用 <code>limit</code> + <code>offset</code> 分段，编号会保持连续。</p><h3 id="搜索、分叉、对照" tabindex="-1">搜索、分叉、对照 <a class="header-anchor" href="#搜索、分叉、对照" aria-label="Permalink to &quot;搜索、分叉、对照&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>session_search(query=&quot;数据库连接超时&quot;, limit=10)</span></span>
<span class="line"><span>session_fork(session_id=&quot;ses_abc123&quot;, message_id=&quot;msg_456&quot;)</span></span>
<span class="line"><span>session_diff(session_id=&quot;ses_abc123&quot;)</span></span></code></pre></div><p>搜索给出命中所在的会话与消息；分叉在感兴趣的分叉点复制出一条新会话；<code>session_diff</code> 用来看某一条会话内部改动了哪些文件。分叉之后两侧独立演进，各自的差异要分别查询。</p><h2 id="排错" tabindex="-1">排错 <a class="header-anchor" href="#排错" aria-label="Permalink to &quot;排错&quot;">​</a></h2><h3 id="会话未找到" tabindex="-1">会话未找到 <a class="header-anchor" href="#会话未找到" aria-label="Permalink to &quot;会话未找到&quot;">​</a></h3><p><code>Session not found: &lt;id&gt;</code> 只会来自 <code>session_read</code> / <code>session_info</code> / <code>session_fork</code> 的前置检查。三种常见原因：ID 拼写或复制不全（用 <code>session_list</code> 重新取完整 ID）；会话属于另一个项目目录——<code>session_list</code> 默认按当前目录过滤，指定 <code>project_path</code> 才能跨项目；会话已被清理或过期。</p><h3 id="搜索无结果" tabindex="-1">搜索无结果 <a class="header-anchor" href="#搜索无结果" aria-label="Permalink to &quot;搜索无结果&quot;">​</a></h3><p><code>session_search</code> 是子串匹配：查询词必须真的出现在消息文本里。默认不搜工具输出，打开 <code>include_tool_output</code> 才覆盖；跨会话搜索只扫前 200 个会话，命不中时先用 <code>session_id</code> 把范围收窄到单条会话再搜。</p><h3 id="差异或统计为空" tabindex="-1">差异或统计为空 <a class="header-anchor" href="#差异或统计为空" aria-label="Permalink to &quot;差异或统计为空&quot;">​</a></h3><p><code>session_diff</code> 返回 <code>No file changes in this session.</code> 说明这条会话没有文件变更，或 <code>message_id</code> 过滤掉了它们。<code>session_info</code> 的 token 与成本全为零，通常意味着适配器没有提供这层元数据，或该会话的助手消息没有附带 token 统计——这不影响消息数、工具频次与文件变更等其他分项。</p><h2 id="实现模块" tabindex="-1">实现模块 <a class="header-anchor" href="#实现模块" aria-label="Permalink to &quot;实现模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>职责</th></tr></thead><tbody><tr><td><code>src/platform/ports/session-client.ts</code></td><td><code>ISessionClient</code> 端口定义</td></tr><tr><td><code>src/platform/adapters/opencode/session.ts</code></td><td>OpenCode 适配器（旧名 <code>SessionClientWrapper</code>）</td></tr><tr><td><code>src/platform/adapters/pi/session.ts</code></td><td>Pi 适配器</td></tr><tr><td><code>src/platform/adapters/dsh/session.ts</code></td><td>dsh 适配器</td></tr><tr><td><code>src/session/session-browse-tools.ts</code></td><td><code>session_list</code> 与 <code>session_search</code></td></tr><tr><td><code>src/session/session-inspect-tools.ts</code></td><td><code>session_read</code> / <code>session_info</code> / <code>session_diff</code> / <code>session_fork</code></td></tr><tr><td><code>src/session/tool-helpers.ts</code></td><td><code>shortId</code>、子串匹配、上下文窗口、会话统计汇总</td></tr><tr><td><code>src/session/formatters.ts</code></td><td>列表表格、消息渲染、统计块、差异块、搜索结果的格式化</td></tr><tr><td><code>src/session/types.ts</code></td><td>会话域的全部类型</td></tr><tr><td><code>src/session/tools.ts</code></td><td>六个工具工厂的统一再导出</td></tr><tr><td><code>src/platform/tool-assembly.ts</code></td><td>有 <code>sessionClient</code> 时注册六个工具</td></tr></tbody></table><h2 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h2><blockquote><p>自 v0.17.0 起，rolebox 提供六个会话内省工具；自 v1.8.0 起，会话列表与搜索表格输出完整 ID，不再截断为 12 字符。</p></blockquote>`,64)])])}const u=o(c,[["render",a]]);export{f as __pageData,u as default};
